import { createHash } from 'node:crypto';

const REPRODUCER_KINDS = new Set(['scenario', 'route', 'command-id']);
const SENSITIVE_KEYS = new Set([
  'rawprompt',
  'prompt',
  'messages',
  'body',
  'authorization',
  'apikey',
  'headers',
]);
const SECRET_PATTERNS = [
  /\bsk-[A-Za-z0-9_-]{8,}\b/,
  /\bphc_[A-Za-z0-9_-]{8,}\b/,
  /\bghp_[A-Za-z0-9_-]{8,}\b/,
  /\bAKIA[0-9A-Z]{12,}\b/,
  /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/,
];

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalizeKey(key) {
  return String(key).toLowerCase().replace(/[^a-z0-9]/g, '');
}

function findSensitive(value, location = '$') {
  if (typeof value === 'string') {
    for (const pattern of SECRET_PATTERNS) {
      if (pattern.test(value)) {
        return { location, reason: `credential-like value (${pattern.source})` };
      }
    }
    return null;
  }
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const found = findSensitive(value[index], `${location}[${index}]`);
      if (found) return found;
    }
    return null;
  }
  if (isObject(value)) {
    for (const [key, child] of Object.entries(value)) {
      const normalized = normalizeKey(key);
      if (SENSITIVE_KEYS.has(normalized)) {
        return { location: `${location}.${key}`, reason: `sensitive field ${key}` };
      }
      const found = findSensitive(child, `${location}.${key}`);
      if (found) return found;
    }
  }
  return null;
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (isObject(value)) {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, stableValue(value[key])]),
    );
  }
  return value;
}

function digest(value) {
  return createHash('sha256').update(JSON.stringify(stableValue(value))).digest('hex');
}

function firstDefined(object, names) {
  for (const name of names) {
    if (object && object[name] !== undefined && object[name] !== null) return object[name];
  }
  return undefined;
}

function boundedText(value, fallback) {
  if (typeof value !== 'string' && typeof value !== 'number') return fallback;
  const text = String(value);
  return text.length <= 200 ? text : `${text.slice(0, 197)}...`;
}

function normalizeReproducer(trace) {
  const supplied = isObject(trace.reproducer) ? trace.reproducer : {};
  const kind = firstDefined(supplied, ['kind']);
  if (!REPRODUCER_KINDS.has(kind)) {
    throw new Error(`reproducer.kind must be one of: ${[...REPRODUCER_KINDS].join(', ')}`);
  }
  if (kind === 'scenario') {
    const id = firstDefined(supplied, ['id', 'scenarioId']) ?? firstDefined(trace, ['scenarioId']);
    if (id === undefined) throw new Error('scenario reproducer requires id');
    return { kind, id: boundedText(id, 'scenario') };
  }
  if (kind === 'route') {
    const route = firstDefined(supplied, ['route', 'path']) ?? firstDefined(trace, ['route', 'path']);
    if (route === undefined) throw new Error('route reproducer requires route');
    return { kind, route: boundedText(route, '/') };
  }
  const commandId = firstDefined(supplied, ['commandId']) ?? firstDefined(trace, ['commandId']);
  if (commandId === undefined) throw new Error('command-id reproducer requires commandId');
  return { kind, commandId: boundedText(commandId, 'command') };
}

function normalizeSelector(trace) {
  const supplied = isObject(trace.selector) ? trace.selector : {};
  const runId = firstDefined(supplied, ['runId']) ?? firstDefined(trace, ['runId']);
  const attempt = firstDefined(supplied, ['attempt']) ?? firstDefined(trace, ['attempt']);
  if (runId === undefined || runId === null || String(runId).length === 0) {
    throw new Error('selector requires runId');
  }
  if (attempt === undefined || attempt === null || String(attempt).length === 0) {
    throw new Error('selector requires attempt');
  }
  return { runId: boundedText(runId, ''), attempt: boundedText(attempt, '') };
}

function outcomeOf(trace) {
  const value = String(firstDefined(trace, ['outcome', 'status', 'result']) ?? '').toLowerCase();
  if (['failed', 'failure', 'error'].includes(value)) return 'failed';
  if (['succeeded', 'success', 'passed', 'pass', 'rejected', 'cancelled', 'canceled'].includes(value)) {
    return value === 'passed' || value === 'pass' ? 'passed' : value;
  }
  if (trace.failed === true) return 'failed';
  return 'passed';
}

/**
 * Convert one already-redacted trace into a deterministic, replayable eval sample.
 * The input is never modified. A trace containing a sensitive field or credential
 * is rejected before any sample or diagnostic containing its payload is returned.
 */
export function traceToEvalSample(trace, options = {}) {
  if (!isObject(trace)) throw new TypeError('trace must be an object');
  const sensitive = findSensitive(trace);
  if (sensitive) {
    const error = new Error(`trace rejected: ${sensitive.reason}`);
    error.code = 'TRACE_NOT_REDACTED';
    error.location = sensitive.location;
    throw error;
  }

  const reproducer = normalizeReproducer(trace);
  const selector = normalizeSelector(trace);
  const outcome = outcomeOf(trace);
  const before = outcome === 'failed' ? 'fail' : 'pass';
  const after = 'pass';
  const basis = {
    schemaVersion: 1,
    reproducer,
    selector,
    expectations: {
      'before-fix': before,
      'after-fix': after,
    },
  };
  const sampleId = options.sampleId ?? `${selector.runId}:${selector.attempt}`;
  const sample = {
    id: boundedText(sampleId, 'trace-sample'),
    schemaVersion: 1,
    reproducer,
    selector,
    'before-fix': { expectation: before },
    'after-fix': { expectation: after },
    expectations: {
      'before-fix': before,
      'after-fix': after,
    },
    digest: digest(basis),
  };
  return sample;
}

export const convertTraceToEvalSample = traceToEvalSample;

/**
 * Explicitly convert only the traces selected by the caller. `selectedRunIds` is
 * required for batch conversion; it is never inferred from all available traces.
 */
export function convertSelectedTraces(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError('traces must be an array');
  const selected = options.selectedRunIds;
  if (!Array.isArray(selected)) throw new TypeError('selectedRunIds must be an array');
  const selectedSet = new Set(selected.map(String));
  const samples = [];
  const rejected = [];
  for (const trace of traces) {
    const runId = isObject(trace) ? firstDefined(trace, ['runId']) : undefined;
    if (runId === undefined || !selectedSet.has(String(runId))) continue;
    try {
      samples.push(traceToEvalSample(trace, options));
    } catch (error) {
      rejected.push({
        runId: runId === undefined ? null : String(runId),
        code: error.code ?? 'TRACE_REJECTED',
        reason: error.message,
      });
    }
  }
  return { samples, rejected };
}

export const traceToEvalSamples = convertSelectedTraces;

export function isTraceRedacted(trace) {
  return findSensitive(trace) === null;
}

export default traceToEvalSample;

export type Reproducer =
  | { kind: 'scenario'; id: string }
  | { kind: 'route'; route: string }
  | { kind: 'command-id'; commandId: string };

export interface TraceSelector {
  runId: string;
  attempt: string | number;
}

export interface TraceToEvalOptions {
  selectedRunIds?: string[];
  sampleId?: string;
}

export interface EvalSample {
  id: string;
  schemaVersion: 1;
  reproducer: Reproducer;
  selector: TraceSelector;
  'before-fix': { expectation: 'fail' | 'pass' };
  'after-fix': { expectation: 'pass' };
  expectations: { 'before-fix': 'fail' | 'pass'; 'after-fix': 'pass' };
  digest: string;
}

export interface RejectedTrace {
  runId: string | null;
  code: string;
  reason: string;
}

export function traceToEvalSample(trace: Record<string, unknown>, options?: TraceToEvalOptions): EvalSample;

export function convertTraceToEvalSample(trace: Record<string, unknown>, options?: TraceToEvalOptions): EvalSample;

export function convertSelectedTraces(
  traces: Record<string, unknown>[],
  options: TraceToEvalOptions & { selectedRunIds: string[] },
): { samples: EvalSample[]; rejected: RejectedTrace[] };

export function traceToEvalSamples(
  traces: Record<string, unknown>[],
  options: TraceToEvalOptions & { selectedRunIds: string[] },
): { samples: EvalSample[]; rejected: RejectedTrace[] };

export function isTraceRedacted(trace: Record<string, unknown>): boolean;

export default traceToEvalSample;

