  /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/,
];

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function normalizeKey(key) {
  return String(key).toLowerCase().replace(/[^a-z0-9]/g, '');
}

function findSensitive(value, location = '$') {
  if (typeof value === 'string') {
    for (const pattern of SECRET_PATTERNS) {
      if (pattern.test(value)) {
        return { location, reason: `credential-like value (${pattern.source})` };
      }
    }
    return null;
  }
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const found = findSensitive(value[index], `${location}[${index}]`);
      if (found) return found;
    }
    return null;
  }
  if (isObject(value)) {
    for (const [key, child] of Object.entries(value)) {
      const normalized = normalizeKey(key);
      if (SENSITIVE_KEYS.has(normalized)) {
        return { location: `${location}.${key}`, reason: `sensitive field ${key}` };
      }
      const found = findSensitive(child, `${location}.${key}`);
      if (found) return found;
    }
  }
  return null;
}

