/**
 * Explicitly convert only the traces selected by the caller. `selectedRunIds` is
 * required for batch conversion; it is never inferred from all available traces.
 */
export function convertSelectedTraces(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError('traces must be an array');
  const selected = options.selectedRunIds;
  if (!Array.isArray(selected)) throw new TypeError('selectedRunIds must be an array');
  const selectedSet = new Set(selected.map(String));
